// Some portions generated by Co-Pilot
import React from "react";
import { render, cleanup, screen } from "@testing-library/react";
import { describe, it, expect, afterEach, vi } from "vitest";
import StatsNav from "../index";

// Mock next/navigation and i18n/navigation Link
vi.mock("next/navigation", () => ({
  usePathname: () => "/stats/download",
}));
vi.mock("@/i18n/navigation", () => ({
  Link: ({
    href,
    className,
    children,
    scroll,
    ...props
  }: {
    href: string;
    className?: string;
    children: React.ReactNode;
    scroll?: boolean;
  }) => (
    <a
      href={href}
      className={className}
      data-scroll={String(scroll)}
      {...props}
    >
      {children}
    </a>
  ),
}));

describe("StatsNav", () => {
  afterEach(() => {
    cleanup();
  });

  it("matches snapshot", () => {
    const { container } = render(<StatsNav />);
    expect(container.firstChild).toMatchSnapshot();
  });

  it("preserves scroll position when switching either statistics tab", () => {
    render(<StatsNav />);
    expect(screen.getAllByRole("link")).toHaveLength(2);
    screen.getAllByRole("link").forEach((link) => {
      expect(link).toHaveAttribute("data-scroll", "false");
    });
  });
});
